-- Section 2013: Reading Passage 3: How Stress Affects Our Judgement
INSERT INTO sections (id, test_id, type, title, instructions, audio_url, passage_text, order_index) VALUES
(2013, 201, 'reading', 'Reading Passage 3: How Stress Affects Our Judgement', '<div class="ielts-reading-container"><h2 class="ielts-reading-question-section-heading">
                                            Questions 27-30                                                                                                                                                
                                                                                                                                    </h2>
                                        <div class="ielts-reading-question-section-content">
                                            <p>Choose the correct letter,<strong> A, B, C or D.</strong></p>
<p>Write the correct letter in boxes on your answer sheet.</p>
                                        </div>
                                        <div class="ielts-reading-questions">
                                                                                                                                                                                            <div class="ielts-standalone-q" data-qnum="27"><div class="ielts-q-header"><strong class="ielts-q-badge">27</strong><span class="ielts-q-title"><span>In the first paragraph, the writer introduces the topic of the text by</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="27" name="question_27" value="A"><span class="ielts-radio-text"><strong>A</strong> defining some commonly used terms.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="27" name="question_27" value="B"><span class="ielts-radio-text"><strong>B</strong> questioning a widely held assumption.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="27" name="question_27" value="C"><span class="ielts-radio-text"><strong>C</strong> mentioning a challenge faced by everyone.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="27" name="question_27" value="D"><span class="ielts-radio-text"><strong>D</strong> specifying a situation which makes us most anxious.</span></label></div></div><div class="ielts-standalone-q" data-qnum="28"><div class="ielts-q-header"><strong class="ielts-q-badge">28</strong><span class="ielts-q-title"><span>What point does the writer make about firefighters in the second paragraph?</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="28" name="question_28" value="A"><span class="ielts-radio-text"><strong>A</strong> The regular changes of stress levels in their working lives make them ideal study subjects.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="28" name="question_28" value="B"><span class="ielts-radio-text"><strong>B</strong> The strategies they use to handle stress are of particular interest to researchers.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="28" name="question_28" value="C"><span class="ielts-radio-text"><strong>C</strong> The stressful nature of their job is typical of many public service professions.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="28" name="question_28" value="D"><span class="ielts-radio-text"><strong>D</strong> Their personalities make them especially well-suited to working under stress.</span></label></div></div><div class="ielts-standalone-q" data-qnum="29"><div class="ielts-q-header"><strong class="ielts-q-badge">29</strong><span class="ielts-q-title"><span>What is the writer doing in the fourth paragraph?</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="29" name="question_29" value="A"><span class="ielts-radio-text"><strong>A</strong> Explaining their findings</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="29" name="question_29" value="B"><span class="ielts-radio-text"><strong>B</strong> Justifying their approach</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="29" name="question_29" value="C"><span class="ielts-radio-text"><strong>C</strong> Setting out their objectives</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="29" name="question_29" value="D"><span class="ielts-radio-text"><strong>D</strong> Describing their methodology</span></label></div></div><div class="ielts-standalone-q" data-qnum="30"><div class="ielts-q-header"><strong class="ielts-q-badge">30</strong><span class="ielts-q-title"><span>In the seventh paragraph, the writer describes a mechanism in the brain which</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="30" name="question_30" value="A"><span class="ielts-radio-text"><strong>A</strong> Enables people to respond more quickly to stressful situations.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="30" name="question_30" value="B"><span class="ielts-radio-text"><strong>B</strong> Results in increased ability to control our levels of anxiety.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="30" name="question_30" value="C"><span class="ielts-radio-text"><strong>C</strong> Produces heightened sensitivity to indications of external threats.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="30" name="question_30" value="D"><span class="ielts-radio-text"><strong>D</strong> Is activated when there is a need to communicate a sense of danger.</span></label></div></div></div>
                                                                                                                                    </div>
                                                                                                                                                            <h2 class="ielts-reading-question-section-heading">
                                            Questions 31-35                                                                                                                                                
