-- Section 2022: Reading Passage 2: Procrastination
INSERT INTO sections (id, test_id, type, title, instructions, audio_url, passage_text, order_index) VALUES
(2022, 202, 'reading', 'Reading Passage 2: Procrastination', '<div class="ielts-reading-container"><h2 class="ielts-reading-question-section-heading">
                                            Questions 14-16                                                                                                                                                
                                                                                                                                    </h2>
                                        <div class="ielts-reading-question-section-content">
                                            <p>Reading Passage has six paragraphs,</p>
<p>Which paragraph contains the following information?</p>
<p>Write the correct letter, <strong>A-F,</strong> in boxes on your answer sheet.</p>
<p><strong>NB</strong> You may use any letter more than once.</p>
                                        </div>
                                        <div class="ielts-reading-questions">
                                                                                                                                                                                                <table class="ielts-reading-matching-table"><thead><tr><th></th><th>A</th><th>B</th><th>C</th><th>D</th><th>E</th><th>F</th></tr></thead><tbody><tr class="ielts-reading-question-item"><td class="ielts-reading-matching-question-cell"><strong id="ielts-reading-question-number-14" class="ielts-q-badge">14</strong> <span>mention of false assumptions about why people procrastinate</span></td>
                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="14" name="question_14" value="A"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="14" name="question_14" value="B"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="14" name="question_14" value="C"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="14" name="question_14" value="D"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="14" name="question_14" value="E"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="14" name="question_14" value="F"></td></tr>                                                                                                                                                                                                                                                                                                    <tr class="ielts-reading-question-item"><td class="ielts-reading-matching-question-cell"><strong id="ielts-reading-question-number-15" class="ielts-q-badge">15</strong> <span>reference to the realisation that others also procrastinate</span></td>
                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="15" name="question_15" value="A"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="15" name="question_15" value="B"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="15" name="question_15" value="C"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="15" name="question_15" value="D"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="15" name="question_15" value="E"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="15" name="question_15" value="F"></td></tr>                                                                                                                                                                                                                                                                                                    <tr class="ielts-reading-question-item"><td class="ielts-reading-matching-question-cell"><strong id="ielts-reading-question-number-16" class="ielts-q-badge">16</strong> <span>neurological evidence of a link between procrastination and emotion</span></td>
                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="16" name="question_16" value="A"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="16" name="question_16" value="B"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="16" name="question_16" value="C"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="16" name="question_16" value="D"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="16" name="question_16" value="E"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="16" name="question_16" value="F"></td></tr></tbody></table>                                                                                                                                                                                        </div>
                                                                                                                                                            <h2 class="ielts-reading-question-section-heading">
                                            Questions 17-22                                                                                                                                                
                                                                                                                                    </h2>
                                        <div class="ielts-reading-question-section-content">
                                            <div class="ielts-reading-section-content-wrapper"><p>Complete the summary below.</p>
<p>Choose <strong>ONE WORD ONLY </strong>from the passage for each answer.</p>
<p>Write your answers in boxes on your answer sheet.</p>
<p><strong>What makes us procrastinate?</strong></p>
<p>Many people think that procrastination is the result of <span class="ielts-reading-question-item"><span class="ielts-inline-input-wrap"><strong class="ielts-q-badge">17</strong><input type="text" data-qnum="17" name="question_17" class="ielts-inline-input" placeholder="[17] javob..." autocomplete="off" spellcheck="false"></span></span></p>
<p>Others believe it to be the result of an inability to organise time efficiently.</p>
<p>But scientific studies suggest that procrastination is actually due to poor mood management. The tasks we are most likely to put off are those that could damage our self-esteem or cause us to feel <span class="ielts-reading-question-item"><span class="ielts-inline-input-wrap"><strong class="ielts-q-badge">18</strong><input type="text" data-qnum="18" name="question_18" class="ielts-inline-input" placeholder="[18] javob..." autocomplete="off" spellcheck="false"></span></span>. when we think about them. Research comparing chronic procrastinators with other people even found differences in the brain regions associated with regulating emotions and identifying <span class="ielts-reading-question-item"><span class="ielts-inline-input-wrap"><strong class="ielts-q-badge">19</strong><input type="text" data-qnum="19" name="question_19" class="ielts-inline-input" placeholder="[19] javob..." autocomplete="off" spellcheck="false"></span></span>.</p>
<p>Emotionally loaded and difficult tasks often cause us to procrastinate.</p>
<p>Getting ready to take <span class="ielts-reading-question-item"><span class="ielts-inline-input-wrap"><strong class="ielts-q-badge">20</strong><input type="text" data-qnum="20" name="question_20" class="ielts-inline-input" placeholder="[20] javob..." autocomplete="off" spellcheck="false"></span></span> might be a typical example of one such task.</p>
<p>People who are likely to procrastinate tend to be either <span class="ielts-reading-question-item"><span class="ielts-inline-input-wrap"><strong class="ielts-q-badge">21</strong><input type="text" data-qnum="21" name="question_21" class="ielts-inline-input" placeholder="[21] javob..." autocomplete="off" spellcheck="false"></span></span> or those with low self-esteem.</p>
<p>Procrastination is only a short-term measure for managing emotions. It’s often followed by a feeling of <span class="ielts-reading-question-item"><span class="ielts-inline-input-wrap"><strong class="ielts-q-badge">22</strong><input type="text" data-qnum="22" name="question_22" class="ielts-inline-input" placeholder="[22] javob..." autocomplete="off" spellcheck="false"></span></span>, which worsens our mood and leads to more procrastination.</p>
</div>                                        </div>
