-- Section 2031: Reading Passage 1: Frozen Food
INSERT INTO sections (id, test_id, type, title, instructions, audio_url, passage_text, order_index) VALUES
(2031, 203, 'reading', 'Reading Passage 1: Frozen Food', '<div class="ielts-reading-container"><h2 class="ielts-reading-question-section-heading">
                                            Questions 1-7                                                                                                                                                                                                    
                                                                                                                                    </h2>
                                        <div class="ielts-reading-question-section-content">
                                            <div class="ielts-reading-section-content-wrapper"><p data-start="92" data-end="198">Complete the notes below.<br data-start="137" data-end="140" /><strong data-start="140" data-end="164">Choose ONE WORD ONLY</strong> from the passage for each answer.</p>
<p class="ielts-reading-passage-subhead"><strong><strong>The history of frozen food</strong></strong></p>
<p data-start="237" data-end="373"><strong data-start="237" data-end="271">2,000 years ago, South America</strong><br data-start="271" data-end="274" />- People conserved the nutritional value of <span class="ielts-reading-question-item"><span class="ielts-inline-input-wrap"><strong class="ielts-q-badge">1</strong><input type="text" data-qnum="1" name="question_1" class="ielts-inline-input" placeholder="[1] javob..." autocomplete="off" spellcheck="false"></span></span>, using a method of freezing then drying.</p>
<p data-start="375" data-end="479"><strong data-start="375" data-end="388">1851, USA</strong><br data-start="388" data-end="391" />- <span class="ielts-reading-question-item"><span class="ielts-inline-input-wrap"><strong class="ielts-q-badge">2</strong><input type="text" data-qnum="2" name="question_2" class="ielts-inline-input" placeholder="[2] javob..." autocomplete="off" spellcheck="false"></span></span> was kept cool by ice during transportation in specially adapted trains.</p>
<p data-start="481" data-end="579"><strong data-start="481" data-end="500">1880, Australia</strong><br data-start="500" data-end="503" />- Two kinds of <span class="ielts-reading-question-item"><span class="ielts-inline-input-wrap"><strong class="ielts-q-badge">3</strong><input type="text" data-qnum="3" name="question_3" class="ielts-inline-input" placeholder="[3] javob..." autocomplete="off" spellcheck="false"></span></span> were the first frozen food shipped to England.</p>
<p data-start="586" data-end="665"><strong data-start="586" data-end="607">1917 onwards, USA</strong><br data-start="607" data-end="610" />- Clarence Birdseye introduced innovations including:</p>
<ul data-start="669" data-end="816">
<li data-start="669" data-end="743">
<p data-start="671" data-end="743">quick-freezing methods, so that <span class="ielts-reading-question-item"><span class="ielts-inline-input-wrap"><strong class="ielts-q-badge">4</strong><input type="text" data-qnum="4" name="question_4" class="ielts-inline-input" placeholder="[4] javob..." autocomplete="off" spellcheck="false"></span></span> did not spoil the food.</p>
</li>
<li data-start="747" data-end="816">
