INSERT INTO sections (id, test_id, type, title, instructions, audio_url, passage_text, order_index) VALUES
(2032, 203, 'reading', 'Reading Passage 2: Can the planet’s coral reefs be saved?', '<div class="ielts-reading-container"><h2 class="ielts-reading-question-section-heading">
