-- Section 2033: Reading Passage 3: Robots and us
INSERT INTO sections (id, test_id, type, title, instructions, audio_url, passage_text, order_index) VALUES
(2033, 203, 'reading', 'Reading Passage 3: Robots and us', '<div class="ielts-reading-container"><h2 class="ielts-reading-question-section-heading">
                                            Questions 27-33                                                                                                                                                
                                                                                                                                    </h2>
                                        <div class="ielts-reading-question-section-content">
                                            <p data-start="241" data-end="349">Match each statement with the correct expert, <strong>A</strong>, <strong>B</strong> or <strong>C</strong>.<br data-start="301" data-end="304" /><em>NB You may use any letter more than once.</em></p>
<p data-start="351" data-end="434"><strong data-start="351" data-end="370">List of Experts</strong><br data-start="370" data-end="373" />A. Martin Rees<br data-start="387" data-end="390" />B. Daniel Wolpert<br data-start="407" data-end="410" />C. Kathleen Richardson</p>
                                        </div>
                                        <div class="ielts-reading-questions">
                                                                                                                                                                                                <table class="ielts-reading-matching-table"><thead><tr><th></th><th>A</th><th>B</th><th>C</th></tr></thead><tbody><tr class="ielts-reading-question-item"><td class="ielts-reading-matching-question-cell"><strong id="ielts-reading-question-number-27" class="ielts-q-badge">27</strong> <span>For our own safety, humans will need to restrict the abilities of robots.</span></td>
                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="27" name="question_27" value="A"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="27" name="question_27" value="B"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="27" name="question_27" value="C"></td></tr>                                                                                                                                                                                                                                                                                                    <tr class="ielts-reading-question-item"><td class="ielts-reading-matching-question-cell"><strong id="ielts-reading-question-number-28" class="ielts-q-badge">28</strong> <span>The risk of robots harming us is less serious than humans believe it to be.</span></td>
                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="28" name="question_28" value="A"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="28" name="question_28" value="B"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="28" name="question_28" value="C"></td></tr>                                                                                                                                                                                                                                                                                                    <tr class="ielts-reading-question-item"><td class="ielts-reading-matching-question-cell"><strong id="ielts-reading-question-number-29" class="ielts-q-badge">29</strong> <span>It will take many decades for robot intelligence to be as imaginative as human intelligence.</span></td>
                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="29" name="question_29" value="A"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="29" name="question_29" value="B"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="29" name="question_29" value="C"></td></tr>                                                                                                                                                                                                                                                                                                    <tr class="ielts-reading-question-item"><td class="ielts-reading-matching-question-cell"><strong id="ielts-reading-question-number-30" class="ielts-q-badge">30</strong> <span>We may have to start considering whether we are treating robots fairly.</span></td>
                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="30" name="question_30" value="A"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="30" name="question_30" value="B"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="30" name="question_30" value="C"></td></tr>                                                                                                                                                                                                                                                                                                    <tr class="ielts-reading-question-item"><td class="ielts-reading-matching-question-cell"><strong id="ielts-reading-question-number-31" class="ielts-q-badge">31</strong> <span>Robots are probably of more help to us on Earth than in space.</span></td>
                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="31" name="question_31" value="A"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="31" name="question_31" value="B"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="31" name="question_31" value="C"></td></tr>                                                                                                                                                                                                                                                                                                    <tr class="ielts-reading-question-item"><td class="ielts-reading-matching-question-cell"><strong id="ielts-reading-question-number-32" class="ielts-q-badge">32</strong> <span>The ideas in high-quality science fiction may prove to be just as accurate as those found in the work of mediocre scientists.</span></td>
                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="32" name="question_32" value="A"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="32" name="question_32" value="B"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="32" name="question_32" value="C"></td></tr>                                                                                                                                                                                                                                                                                                    <tr class="ielts-reading-question-item"><td class="ielts-reading-matching-question-cell"><strong id="ielts-reading-question-number-33" class="ielts-q-badge">33</strong> <span>There are those who look forward to robots developing greater intelligence.</span></td>
                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="33" name="question_33" value="A"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="33" name="question_33" value="B"></td>                                                                                                            <td class="ielts-reading-matching-option-cell"><input type="radio" data-qnum="33" name="question_33" value="C"></td></tr></tbody></table>                                                                                                                                                                                        </div>
                                                                                                                                                            <h2 class="ielts-reading-question-section-heading">
                                            Questions 34-36                                                                                                                                                
                                                                                                                                    </h2>
                                        <div class="ielts-reading-question-section-content">
                                            <p>Complete each sentence with the correct ending, <strong>A–D</strong>, below.</p>
                                        </div>
                                        <div class="ielts-reading-questions">
                                                                                                                                                                                                <div class="ielts-reading-question-item"> • <span>Richardson and Rees express similar views regarding the ethical aspect of</span><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">34</strong><select data-qnum="34" name="question_34" class="ielts-inline-select"><option value="">[ 34 ] Tanlang...</option><option value="A. robots to explore outer space.">A. robots to explore outer space.</option><option value="B. advances made in machine intelligence so far.">B. advances made in machine intelligence so far.</option><option value="C. changes made to other planets for our own benefit.">C. changes made to other planets for our own benefit.</option><option value="D. the harm already done by artificial intelligence.">D. the harm already done by artificial intelligence.</option></select></span></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div class="ielts-reading-question-item"> • <span>Rees and Wolpert share an opinion about the extent of</span><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">35</strong><select data-qnum="35" name="question_35" class="ielts-inline-select"><option value="">[ 35 ] Tanlang...</option><option value="A. robots to explore outer space.">A. robots to explore outer space.</option><option value="B. advances made in machine intelligence so far.">B. advances made in machine intelligence so far.</option><option value="C. changes made to other planets for our own benefit.">C. changes made to other planets for our own benefit.</option><option value="D. the harm already done by artificial intelligence.">D. the harm already done by artificial intelligence.</option></select></span></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div class="ielts-reading-question-item"> • <span>Wolpert disagrees with Richardson on the question of</span><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">36</strong><select data-qnum="36" name="question_36" class="ielts-inline-select"><option value="">[ 36 ] Tanlang...</option><option value="A. robots to explore outer space.">A. robots to explore outer space.</option><option value="B. advances made in machine intelligence so far.">B. advances made in machine intelligence so far.</option><option value="C. changes made to other planets for our own benefit.">C. changes made to other planets for our own benefit.</option><option value="D. the harm already done by artificial intelligence.">D. the harm already done by artificial intelligence.</option></select></span></div>                                                                        <div class="options-dnd-panel dnd-panel" data-dnd-group="1605288">
